import javax.swing.*;import java.awt.*;import java.sql.*;
public class AccountFrame extends JFrame{JTextField cid=new JTextField(),num=new JTextField(),bal=new JTextField();JComboBox<String> type=new JComboBox<>(new String[]{"SAVINGS","CURRENT"});public AccountFrame(){setTitle("Manage Accounts");setSize(620,470);setLocationRelativeTo(null);setDefaultCloseOperation(DISPOSE_ON_CLOSE);JPanel p=new JPanel(null);p.setBackground(new Color(230,240,255));JLabel h=new JLabel("MANAGE ACCOUNTS",SwingConstants.CENTER);h.setFont(new Font("Arial",1,22));h.setBounds(160,25,300,35);p.add(h);lab(p,"Customer ID:",70,90);fld(p,cid,220,90);lab(p,"Account Number:",70,140);fld(p,num,220,140);lab(p,"Account Type:",70,190);type.setBounds(220,190,280,30);p.add(type);lab(p,"Opening Balance:",70,240);fld(p,bal,220,240);JButton b=new JButton("OPEN ACCOUNT");b.setBounds(120,330,170,40);p.add(b);b.addActionListener(e->add());add(p);}void lab(JPanel p,String s,int x,int y){JLabel l=new JLabel(s);l.setBounds(x,y,140,30);p.add(l);}void fld(JPanel p,JTextField f,int x,int y){f.setBounds(x,y,280,30);p.add(f);}void add(){try{int c=Integer.parseInt(cid.getText().trim());double b=Double.parseDouble(bal.getText().trim());if(b<0){JOptionPane.showMessageDialog(this,"Balance cannot be negative!");return;}try(Connection x=DBConnection.getConnection();PreparedStatement q=x.prepareStatement("INSERT INTO BANK_ACCOUNTS(ACCOUNT_ID,CUSTOMER_ID,ACCOUNT_NUMBER,ACCOUNT_TYPE,BALANCE,STATUS) VALUES(BANK_ACCOUNT_SEQ.NEXTVAL,?,?,?,?, 'ACTIVE')")){q.setInt(1,c);q.setString(2,num.getText().trim());q.setString(3,type.getSelectedItem().toString());q.setDouble(4,b);q.executeUpdate();JOptionPane.showMessageDialog(this,"Account Opened Successfully!");}}catch(NumberFormatException e){JOptionPane.showMessageDialog(this,"Customer ID and balance must be numbers!");}catch(SQLException e){JOptionPane.showMessageDialog(this,"Database Error: "+e.getMessage());}}}
